HOW_TO_USE = f"""
1. **Filter** the videos in the sidebar (topic, channel, publication date, minimum views).
2. Move **Minimum similarity for an edge** to decide how alike two videos must be to be connected.
   Higher = fewer, stronger links (default {DEFAULT_THRESHOLD:.2f}).
3. **Overview** gives headline numbers. **Video performance** compares views and engagement.
4. **Topic network** draws the graph - each dot is a video, each line a similarity link.
5. **Centrality & communities** ranks videos by importance, finds groups, and finds bridge videos.
6. **Shortest path** finds the most similar chain of videos between any two videos (Dijkstra).
7. **Data & methodology** shows formulas, limitations and download buttons.

Use *Reset filters* in the sidebar to go back to the defaults. Hover over any dot or bar for details.
"""

SIMILARITY_FORMULA = f"""
**How two videos become connected**

`similarity = min(1, Jaccard(tags A, tags B) + {TOPIC_BONUS} if same topic)`

where `Jaccard = shared tags / all different tags used by either video`.

* Videos must share **at least one tag** to be linked.
* An edge exists when `similarity >= the threshold` you chose in the sidebar.
* **Edge weight** = similarity (bigger = more alike).
* **Edge distance** = `1 / similarity` (smaller = closer). Dijkstra, closeness and betweenness use
  this distance, so a path through very similar videos is "cheap".
"""

CENTRALITY_HELP: dict[str, tuple[str, str]] = {
    "degree": ("Degree", "How many direct connections a video has (shown as a share of all other videos)."),
    "closeness": ("Closeness", "How near a video is to all the videos it can reach, measured with the edge distance."),
    "betweenness": ("Betweenness", "How often a video lies on the lowest-cost paths between other videos - a sign it may bridge groups."),
    "eigenvector": ("Eigenvector", "Connections to other well-connected videos count more than connections to isolated ones."),
    "pagerank": ("PageRank", "Importance passed along links from other important videos. This is a graph measure only - it is NOT YouTube's recommendation or ranking algorithm."),
}

COMMUNITY_HELP = (
    "Communities are groups of videos that are linked to each other more than to the rest of the graph "
    "(found by greedy modularity maximisation). They are **algorithmic groupings**, not guaranteed real-world "
    "categories. **Modularity** measures how clear the split is: values above about 0.3 usually mean visible "
    "community structure."
)

DIJKSTRA_HELP = """
**Dijkstra's algorithm** finds the lowest-total-cost route between two nodes.
It repeatedly takes the cheapest node it has not finished yet and checks whether going through that node
makes any neighbour cheaper to reach. Here the cost of a step is `distance = 1 / similarity`, so the best
path is a chain of videos that are each very similar to the next one. The total cost is the sum of step costs.
"""

PARTITION_HELP = (
    "**Graph partitioning** splits the nodes into groups while cutting as few edges as possible. "
    "The Kernighan-Lin algorithm starts with two balanced halves and swaps pairs of nodes while that reduces "
    "the number of edges between the halves. Detected *communities* (previous tab) are a partition into any number of groups."
)

HIERARCHICAL_HELP = (
    "**Hierarchical clustering** (agglomerative, average linkage) starts with every video alone and repeatedly merges "
    "the two most similar clusters, building a tree called a dendrogram. Cutting the tree at a chosen height gives a "
    "chosen number of clusters. It uses `1 - similarity` as the distance between videos, including pairs below the "
    "edge threshold, so it can differ from the graph communities."
)

SMALL_WORLD_HELP = (
    "**Small-world** networks have high clustering but short paths between any two nodes. "
    "**Scale-free** networks have a few very highly connected hubs and many low-degree nodes. "
    "Below, the dashboard only calculates simple indicators. A network built from a similarity rule is not a real "
    "social network, so treat the numbers as teaching examples, not scientific findings."
)

CORRELATION_WARNING = "Correlation shows that two measures move together. It does **not** show that one causes the other."

